(() => {
  'use strict';
  const el=id=>document.getElementById(id),state={csrf:''};
  async function call(path,method='GET',body){const headers={Accept:'application/json'};if(method!=='GET')headers['X-CSRF-Token']=state.csrf;if(body!==undefined)headers['Content-Type']='application/json';const response=await fetch('/conscious/api/vendor/'+path,{method,credentials:'same-origin',cache:'no-store',headers,body:body===undefined?undefined:JSON.stringify(body)});const data=await response.json().catch(()=>({}));if(!response.ok||!data.success)throw Error(data.message||'Account request failed.');return data;}
  function row(label,value){const wrap=document.createElement('div');wrap.className='vc-info-row';const name=document.createElement('span');name.textContent=label;const info=document.createElement('strong');info.textContent=String(value??'—');wrap.append(name,info);return wrap;}
  function status(text,error=false){el('vac-status').textContent=text;el('vac-status').className='vc-status '+(error?'warning':'info');}
  async function load(){try{const identity=await call('auth/me.php');state.csrf=identity.csrf_token||'';const [onboarding,finance]=await Promise.all([call('onboarding.php'),call('finance-summary.php')]);const vendor=identity.vendor||{},application=onboarding.application||{};const profile=el('vac-profile');profile.replaceChildren(row('Display name',vendor.display_name),row('Vendor type',vendor.vendor_type),row('Email',vendor.email),row('Mobile',vendor.mobile),row('Account status',vendor.status));const verification=el('vac-verification');verification.replaceChildren(row('Application',application.reference),row('Review status',application.status?.replaceAll('_',' ')),row('Completion',application.completion_percent+'%'));if(application.decision_reason)verification.append(row('Review note',application.decision_reason));if(['draft','changes_requested'].includes(application.status)){const link=document.createElement('a');link.className='vc-btn small mt-3';link.href='onboarding.php';link.textContent='Continue onboarding';verification.append(link);}const docs=el('vac-documents');docs.replaceChildren();if(!onboarding.documents?.length)docs.textContent='No documents uploaded yet.';else onboarding.documents.forEach(document=>docs.append(row(document.document_type.replaceAll('_',' '),document.verification_status)));const banks=el('vac-banks');banks.replaceChildren();if(!finance.bank_accounts?.length)banks.textContent='No payout bank account on record.';else finance.bank_accounts.forEach(bank=>banks.append(row('Account ending '+bank.account_last4,bank.verification_status)));status('Account details loaded.');}catch(error){status(error.message,true);}}
  el('vac-logout').addEventListener('click',async()=>{try{await call('auth/logout.php','POST',{});location.replace('/conscious/partner/login');}catch(error){status(error.message,true);}});
  el('vac-bank-form')?.addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;form.classList.add('was-validated');if(!form.checkValidity()){form.querySelector(':invalid')?.focus();status('Complete the highlighted bank details.',true);return;}const values=Object.fromEntries(new FormData(form));const proof=values.bank_proof;delete values.bank_proof;if(values.account_number!==values.account_confirm){el('vac-account-confirm').setCustomValidity('Account numbers do not match.');el('vac-account-confirm').reportValidity();status('Account numbers do not match.',true);return;}if(!proof||proof.size<1||proof.size>5242880||!['image/jpeg','image/png','application/pdf'].includes(proof.type)){status('Choose a JPG, PNG or PDF bank proof under 5 MB.',true);return;}const button=form.querySelector('button[type="submit"]');button.disabled=true;try{await call('bank-account.php','POST',values);const upload=new FormData();upload.append('document_type','bank_proof');upload.append('file',proof);const response=await fetch('/conscious/api/vendor/documents.php',{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','X-CSRF-Token':state.csrf},body:upload});const result=await response.json().catch(()=>({}));if(!response.ok||!result.success)throw Error(result.message||'Bank details were saved, but proof upload failed. Upload the proof before requesting a payout.');form.reset();form.classList.remove('was-validated');await load();status('Bank details and proof submitted for admin review.');}catch(error){status(error.message,true);}finally{button.disabled=false;}});
  el('vac-account-confirm')?.addEventListener('input',event=>event.target.setCustomValidity(''));
  load();
})();
